from itertools import product
from typing import Set, Tuple

Vector = Tuple[int, ...]

def l1_norm(x: Vector) -> int:
    """Taxicab norm sum |x_i|."""
    return sum(abs(c) for c in x)

def l1_ball(d: int, m: int) -> Set[Vector]:
    """All lattice points of the radius-m cross-polytope in Z^d."""
    return {x for x in product(range(-m, m + 1), repeat=d) if l1_norm(x) <= m}

def verify_geometry(max_d: int = 6) -> None:
    """Confirm |B_0^d| = 1, |B_1^d| = 2d+1, and the dilation containment."""
    for d in range(max_d + 1):
        assert len(l1_ball(d, 0)) == 1
        assert len(l1_ball(d, 1)) == 2 * d + 1, d
        print(f"d={d}: |B_0|=1, |B_1|={2*d+1}  verified")
    # dilation: B_m + B_m subset B_{2m}
    d, m = 3, 2
    ball = l1_ball(d, m)
    both = {tuple(a + b for a, b in zip(u, v)) for u in ball for v in ball}
    assert all(l1_norm(x) <= 2 * m for x in both)
    print(f"dilation B_{m}+B_{m} subset B_{2*m} in Z^{d}: verified "
          f"(max norm {max(l1_norm(x) for x in both)})")

if __name__ == "__main__":
    verify_geometry()

