function ITERATED_SUMSET(A_1, ..., A_n):
    acc <- A_1
    for k = 2 to n:
        next <- empty set
        for u in acc:
            for v in A_k:
                next <- next union { u + v }   // componentwise
        acc <- next
    return acc

function CERTIFIED_BRACKET(n, m):
    p_lt_n <- (m + 1 < n*m + 1)          // strict for n >= 2
    p_gt_1 <- (n*m + 1 < (m + 1)^n)      // Bernoulli, strict for n >= 2
    return (p_gt_1, p_lt_n)

function ENUMERATE_L1_BALL(d, m):
    if d = 0: return [ () ]
    out <- []
    for c = -m to m:
        for rest in ENUMERATE_L1_BALL(d - 1, m - |c|):
            out.append( (c,) ++ rest )
    return out
